import java.util.*;

class Solution {
  public long findMaximumScore(List<Integer> nums) {
    long answer = 0;
    int last = 0;
    for (int i = 1; i < nums.size(); i++) {
      if (nums.get(i) > nums.get(last)) {
        answer += (long) (i - last) * nums.get(last);
        last = i;
      }
    }
    return answer + (long) (nums.size() - 1 - last) * nums.get(last);
  }
}
